import { audit } from './accessibility.js';
import { test, expect } from '@playwright/test';
import { MongoMemoryReplSet } from 'mongodb-memory-server';
import { createServer as createVite } from 'vite';
import { mkdtemp, rm, mkdir, writeFile } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import os from 'node:os';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { root } from '../../server/src/config.js';
import { connect, migrate, seed } from '../../server/src/persistence.js';
import { createApplication } from '../../server/src/app.js';
let repl, db, application, vite, folder, browserUrl;
const browserEvidence = path.resolve(process.env.BROWSER_EVIDENCE_DIR || path.join(root, 'evidence'));
async function chooseTrack(page, label, title) {
  const select = page.getByLabel(label, {exact:true});
  const option = select.locator('option').filter({hasText:new RegExp(`^${title} —`)});
  await expect(option).toHaveCount(1);
  await select.selectOption(await option.getAttribute('value'));
}
const received=new Map();
test.beforeEach(async () => {
  received.clear();
  folder = await mkdtemp(path.join(os.tmpdir(), 'dj-browser-assets-'));
  repl = await MongoMemoryReplSet.create({ replSet: { count: 1, storageEngine: 'wiredTiger' } });
  db = await connect(repl.getUri('browser_tests')); await migrate(db.connection, db.models); await seed(db.models);
  const wave = Buffer.alloc(1644);
  wave.write('RIFF'); wave.writeUInt32LE(1636,4); wave.write('WAVEfmt ',8); wave.writeUInt32LE(16,16);
  wave.writeUInt16LE(1,20); wave.writeUInt16LE(1,22); wave.writeUInt32LE(8000,24); wave.writeUInt32LE(16000,28);
  wave.writeUInt16LE(2,32); wave.writeUInt16LE(16,34); wave.write('data',36); wave.writeUInt32LE(1600,40);
  await writeFile(path.join(folder,'browser-fixture.wav'),wave);
  const asset = await db.models.Asset.create({ storageKey:'browser-fixture.wav', mimeType:'audio/wav', byteLength:wave.length, sha256:'test-fixture', licenseLabel:'Original HTTP test silence', sourceAttribution:'Generated for tests only' });
  await db.models.Track.create({ title:'Preview fixture',artist:'Test only',durationSeconds:0.1,assetId:asset._id,profileStatus:'pending',acoustic:null });
  const playable=Buffer.alloc(480044);wave.copy(playable,0,0,44);playable.writeUInt32LE(playable.length-8,4);playable.writeUInt32LE(playable.length-44,40);
  await writeFile(path.join(folder,'playback-fixture.wav'),playable);
  const playbackAsset=await db.models.Asset.create({storageKey:'playback-fixture.wav',mimeType:'audio/wav',byteLength:playable.length,sha256:createHash('sha256').update(playable).digest('hex'),licenseLabel:'Original test silence',sourceAttribution:'Generated only for playback tests'});
  await db.models.Track.updateMany({demoMetadataOnly:true},{$set:{assetId:playbackAsset._id,durationSeconds:30}});
  const config = { key: randomBytes(48).toString('hex'), issuer: 'tests', audience: 'tests', origin: 'http://127.0.0.1', secure: false, assetRoot: folder };
  application = createApplication({ ...db, config, logger: { info() {}, error() {} } });
  const originalCommand=application.rooms.command.bind(application.rooms);
  application.rooms.command=async(...args)=>{const at=performance.timeOrigin+performance.now();const result=await originalCommand(...args);received.set(result.revision,at);return result;};
  await new Promise((resolve, reject) => { application.server.once('error', reject); application.server.listen(0, '127.0.0.1', resolve); });
  const apiUrl = `http://127.0.0.1:${application.server.address().port}`;
  vite = await createVite({ root: path.join(root, 'client'), configFile: path.join(root, 'client/vite.config.js'), server: { port: 0, strictPort: false, proxy: { '/api': apiUrl, '/socket.io': { target: apiUrl, ws: true } } } }); await vite.listen();
  browserUrl = `http://127.0.0.1:${vite.httpServer.address().port}`;
  config.origin = browserUrl;
});
test.afterEach(async () => { await vite?.close(); await application?.close(); await db?.connection.close(); await repl?.stop(); if (folder) await rm(folder, { recursive: true, force: true }); });
